-- window frames: ROWS, RANGE and GROUPS with offsets, EXCLUDE, frames over NULLs, dates and numerics
create table f (id int primary key, p int, v int, d date, n numeric);
insert into f values (1, 1, 1, '2024-01-01', 1.5), (2, 1, 2, '2024-01-02', 2.5), (3, 1, 2, '2024-01-05', null), (4, 1, 4, '2024-02-01', 4), (5, 1, 7, '2024-02-29', 4), (6, 1, null, null, 6.25), (7, 2, 10, '2023-12-31', 1), (8, 2, 10, '2024-01-01', 1), (9, 2, 12, '2024-03-01', 3), (10, 2, null, '2024-03-02', null);
select id, sum(v) over (order by id rows between 1 preceding and 1 following) from f;
select id, sum(v) over (order by id rows between 2 preceding and current row) from f;
select id, sum(v) over (order by id rows between current row and 2 following) from f;
select id, sum(v) over (order by id rows between 2 preceding and 1 preceding) from f;
select id, sum(v) over (order by id rows between 1 following and 3 following) from f;
select id, sum(v) over (order by id rows between unbounded preceding and 1 preceding) from f;
select id, sum(v) over (order by id rows between 1 following and unbounded following) from f;
select id, sum(v) over (order by id rows between unbounded preceding and unbounded following) from f;
select id, sum(v) over (order by id rows 2 preceding) from f;
select id, sum(v) over (order by id rows unbounded preceding) from f;
select id, sum(v) over (order by id rows current row) from f;
select id, count(*) over (order by id rows between 0 preceding and 0 following) from f;
select id, sum(v) over (partition by p order by id rows between 1 preceding and 1 following) from f;
select id, sum(v) over (order by id rows between 3 following and 1 following) from f;
select id, sum(v) over (order by id rows between current row and 1 preceding) from f;
select id, sum(v) over (order by id rows between unbounded following and current row) from f;
select id, sum(v) over (order by id rows between current row and unbounded preceding) from f;
select id, sum(v) over (order by id rows between -1 preceding and current row) from f;
select id, sum(v) over (order by id rows between null preceding and current row) from f;
select id, v, sum(v) over (order by v range between unbounded preceding and current row) from f;
select id, v, sum(v) over (order by v range between current row and unbounded following) from f;
select id, v, sum(v) over (order by v range current row) from f;
select id, v, sum(id) over (order by v range between 1 preceding and 1 following) from f;
select id, v, sum(id) over (order by v range between 2 preceding and current row) from f;
select id, v, sum(id) over (order by v desc range between 2 preceding and current row) from f;
select id, v, sum(id) over (order by v nulls first range between 2 preceding and 2 following) from f;
select id, v, sum(id) over (order by v desc nulls last range between 1 preceding and 3 following) from f;
select id, v, count(*) over (partition by p order by v range between 5 preceding and 0 following) from f;
select id, v, count(*) over (order by v range between 3 following and 5 following) from f;
select id, v, count(*) over (order by v range between 5 preceding and 3 preceding) from f;
select id, d, count(*) over (order by d range between interval '3 days' preceding and current row) from f;
select id, d, count(*) over (order by d range between interval '1 month' preceding and interval '1 day' following) from f;
select id, d, count(*) over (order by d desc range between current row and interval '30 days' following) from f;
select id, n, sum(n) over (order by n range between 1.5 preceding and 1.5 following) from f;
select id, n, count(*) over (order by n range between 0.5 preceding and current row) from f;
select id, v, sum(id) over (order by v range between 1 preceding and current row) from f where v is not null;
select id, sum(v) over (order by v, id range between 1 preceding and current row) from f;
select id, sum(v) over (range between 1 preceding and current row) from f;
select id, sum(v) over (order by d range between 1 preceding and current row) from f;
select id, sum(v) over (order by v range between -1 preceding and current row) from f;
select id, sum(v) over (order by v range between 1.5 preceding and current row) from f;
select id, sum(v) over (order by id range between 1 preceding and current row) from f;
select id, v, sum(id) over (order by v groups between 1 preceding and 1 following) from f;
select id, v, sum(id) over (order by v groups between current row and current row) from f;
select id, v, sum(id) over (order by v groups between unbounded preceding and current row) from f;
select id, v, sum(id) over (order by v groups between 2 following and unbounded following) from f;
select id, v, sum(id) over (order by v desc groups between 1 preceding and 1 preceding) from f;
select id, v, count(*) over (partition by p order by v groups 1 preceding) from f;
select id, sum(v) over (groups between 1 preceding and current row) from f;
select id, v, sum(id) over (order by v groups between -1 preceding and current row) from f;
select id, v, sum(id) over (order by v rows between unbounded preceding and unbounded following exclude current row) from f;
select id, v, sum(id) over (order by v range between unbounded preceding and unbounded following exclude group) from f;
select id, v, sum(id) over (order by v range between unbounded preceding and unbounded following exclude ties) from f;
select id, v, sum(id) over (order by v range between unbounded preceding and unbounded following exclude no others) from f;
select id, v, sum(id) over (order by v, id rows between 1 preceding and 1 following exclude current row) from f;
select id, v, array_agg(id) over (order by v, id rows between 2 preceding and 2 following exclude current row) from f;
select id, v, count(*) over (order by v groups between 1 preceding and 1 following exclude group) from f;
select id, v, sum(id) over (order by v groups between 1 preceding and 1 following exclude ties) from f;
select id, v, sum(id) over (order by v range between 2 preceding and 2 following exclude current row) from f;
select id, v, first_value(id) over (order by v, id rows between 1 preceding and 1 following exclude current row) from f;
select id, v, last_value(id) over (order by v, id rows between 1 preceding and 1 following exclude current row) from f;
select id, v, nth_value(id, 2) over (order by v, id rows between 2 preceding and 2 following exclude current row) from f;
select id, v, first_value(id) over (order by v range between current row and current row exclude group) from f;
select id, v, sum(id) over (partition by p order by v range between unbounded preceding and current row exclude ties) from f;
select id, v, sum(id) over (order by v rows between current row and current row exclude current row) from f;
select id, v, sum(id) over (exclude current row) from f;
select id, v, sum(id) over (order by v exclude ties) from f;
select id, first_value(v) over (order by id rows between 2 preceding and current row), last_value(v) over (order by id rows between current row and 2 following) from f;
select id, nth_value(v, 2) over (order by id rows between 1 preceding and 1 following) from f;
select id, nth_value(v, 3) over (partition by p order by id range between unbounded preceding and unbounded following) from f;
select id, min(v) over (order by id rows between 2 preceding and 2 following), max(v) over (order by id rows between 2 preceding and 2 following) from f;
select id, avg(v) over (order by id rows between 2 preceding and current row) from f;
select id, avg(n) over (order by id rows between 1 preceding and 1 following) from f;
select id, count(v) over (order by id rows between 3 preceding and current row), count(*) over (order by id rows between 3 preceding and current row) from f;
select id, string_agg(v::text, ',') over (order by id rows between 2 preceding and current row) from f;
select id, array_agg(v) over (partition by p order by id rows between 1 following and 2 following) from f;
select id, bool_and(v > 1) over (order by id rows between 1 preceding and current row) from f;
select id, stddev(v) over (order by id rows between 2 preceding and current row) from f;
select id, variance(n) over (order by id rows between 2 preceding and current row) from f;
select id, sum(v) filter (where v > 2) over (order by id rows between 2 preceding and current row) from f;
select id, sum(distinct v) over (order by id rows between 2 preceding and current row) from f;
select id, row_number() over (order by id rows between 1 preceding and 1 following), rank() over (order by v rows 1 preceding) from f;
select id, lag(v) over (order by id rows between current row and current row), lead(v) over (order by id rows between current row and current row) from f;
select id, ntile(3) over (order by id rows between current row and current row) from f;
select id, sum(v) over w from f window w as (order by id rows between 1 preceding and 1 following);
select id, sum(v) over w, avg(v) over w from f window w as (partition by p order by v range between 2 preceding and 2 following);
select id, sum(v) over (w rows between 1 preceding and current row) from f window w as (partition by p order by id);
select id, sum(v) over (w range between 1 preceding and current row) from f window w as (partition by p order by v);
select id, sum(v) over (order by id rows between 1 preceding and 1 following) from f where p = 2;
select id, sum(v) over (order by id rows between 1 preceding and 1 following) from f order by id desc;
select sum(s) from (select sum(v) over (order by id rows between 1 preceding and 1 following) s from f) t;
select id, sum(v) over (order by id rows between 1 preceding and 1 following) - v from f;
select x, sum(x) over (order by x rows between 1 preceding and 1 following), sum(x) over (order by x range between 1 preceding and 1 following) from generate_series(1, 6) x;
select x, count(*) over (order by x range between 2 preceding and 2 following) from (values (1), (1), (2), (4), (7), (7), (8)) t(x);
select x, count(*) over (order by x groups between 1 preceding and 1 following) from (values (1), (1), (2), (4), (7), (7), (8)) t(x);
select x, sum(x) over (order by x desc range between 2 preceding and current row) from (values (1), (1), (2), (4), (7), (7), (8)) t(x);
select x, count(*) over (order by x range between 0.5 preceding and 0.5 following) from (values (1.0), (1.4), (1.6), (2.2)) t(x);
select x, count(*) over (order by x range between 0.5 preceding and 0.5 following) from (values (1.0::float8), (1.4::float8), (1.6::float8), (2.2::float8)) t(x);
select x, count(*) over (order by x range between 'infinity' preceding and current row) from (values (1.0::float8), (2::float8)) t(x);
select x, count(*) over (order by x range between interval '1 hour' preceding and current row) from (values (timestamp '2024-01-01 10:00'), (timestamp '2024-01-01 10:30'), (timestamp '2024-01-01 12:00')) t(x);
select x, count(*) over (order by x range between interval '1 hour' preceding and current row) from (values (time '10:00'), (time '10:30'), (time '12:00')) t(x);
select x, count(*) over (order by x range between interval '1 day' preceding and current row) from (values (timestamptz '2024-01-01 10:00+00'), (timestamptz '2024-01-02 09:00+00'), (timestamptz '2024-01-03 12:00+00')) t(x);
select x, count(*) over (order by x range between 1 preceding and current row) from (values (interval '1 hour')) t(x);
select x, count(*) over (order by x range between 1 preceding and current row) from (values ('a'), ('b')) t(x);
select x, count(*) over (order by x range between 2 preceding and 2 following) from (values (32767::smallint), (32766::smallint), (-32768::smallint)) t(x);
select x, count(*) over (order by x range between 1 preceding and 1 following) from (values (2147483647), (2147483646), (-2147483648)) t(x);
select x, count(*) over (order by x range between 9223372036854775807 preceding and 9223372036854775807 following) from (values (1::bigint), (9223372036854775807::bigint), (-9223372036854775808::bigint)) t(x);
select patron_id, points, avg(points) over (order by points, patron_id rows between 2 preceding and 2 following) from patron where patron_id <= 40;
select patron_id, points, count(*) over (order by points range between 10 preceding and 10 following) from patron where patron_id <= 40;
select person_id, fee, sum(fee) over (order by fee range between 50 preceding and 50 following) from artist;
select person_id, fee, count(*) over (partition by company_id order by fee groups between 1 preceding and 1 following exclude current row) from artist;
select perf_date, count(*) over (order by perf_date range between interval '3 days' preceding and interval '3 days' following) from performance;
